#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Publishes Football Results under ReccaFlames (roadmap item 19, ADR 0009):
# GitHub repository, PyPI (football-results-cli), and the MCP Registry
# (io.github.ReccaFlames/football-results). Run from the repository root:
#   bash scripts/publish-wizard.sh

OWNER="ReccaFlames"
REPO="football-results-api"
SLUG="$OWNER/$REPO"
RELEASE_VERSION="${RELEASE_VERSION:-1.0.0}"

run_wizard() {

TOTAL_STAGES=9

banner "Publish Football Results as $SLUG v$RELEASE_VERSION"

stage "Prerequisites"
say "Publishing runs as the GitHub account $OWNER, from a clean checkout."
command -v gh >/dev/null || { warn "install the GitHub CLI (gh) first"; exit 1; }
command -v uv >/dev/null || { warn "install uv first"; exit 1; }
step "If gh is logged in as another account, run: gh auth login (choose $OWNER)"
pause "Press Enter once gh is logged in as $OWNER"
login=$(gh api user --jq .login)
[[ "$login" == "$OWNER" ]] || { warn "gh is logged in as $login, not $OWNER"; exit 1; }
if [[ -n "$(git status --porcelain)" ]]; then warn "commit or stash your changes first"; exit 1; fi
say "Running lint and unit tests..."
uv run ruff check . && uv run ruff format --check . && uv run pytest -q
pause

stage "Secret and privacy scan"
say "Everything in the git history becomes public. Scanning it with gitleaks..."
if command -v gitleaks >/dev/null; then gitleaks git --redact .
elif command -v docker >/dev/null; then
  docker run --rm -v "$PWD:/repo" zricethezav/gitleaks:latest git --redact /repo
else warn "install gitleaks (brew install gitleaks) or Docker, then re-run"; exit 1; fi
say "Commit author emails that will be published:"
git log --format='    %an <%ae>' | sort -u
note "To hide an email, rewrite history before pushing (git filter-repo --mailmap ...)."
confirm "No leaks and the emails are fine to publish?" || exit 1

stage "Create the GitHub repository"
if gh repo view "$SLUG" >/dev/null 2>&1; then
  say "$SLUG already exists."
else
  confirm "Create public repository $SLUG and push the current branch?" || exit 1
  gh repo create "$SLUG" --public --source . --remote origin --push \
    --description "Football fixtures, results, and league tables for AI agents: REST, CLI, MCP"
fi
open_url "https://github.com/$SLUG/actions"
step "Check that the CI workflow runs green on the pushed branch."
pause

stage "GitHub environment for PyPI"
gh api -X PUT "repos/$SLUG/environments/pypi" >/dev/null
say "Created (or kept) the environment 'pypi' that release.yml publishes from."
open_url "https://github.com/$SLUG/settings/environments"
step "Open 'pypi' → Deployment branches and tags → Selected branches and tags."
step "Add a tag rule 'v*' (optional: add yourself under Required reviewers)."
pause "Press Enter once the environment is restricted"

stage "PyPI trusted publisher"
say "PyPI accepts the release workflow's OIDC token instead of an API token."
open_url "https://pypi.org/manage/account/publishing/"
step "Log in (create the account and enable 2FA if needed)."
step "Under 'Add a new pending publisher' → GitHub, enter:"
note "    PyPI Project Name: football-results-cli"
note "    Owner: $OWNER    Repository name: $REPO"
note "    Workflow name: release.yml    Environment name: pypi"
step "Click 'Add'."
pause "Press Enter once the pending publisher is listed"

stage "Demo host"
say "The demo must be live first (docs/DEMO.md). Its host becomes the CLI default"
say "URL and the first remote in server.json (ADR 0009)."
ask DEMO_HOST "Demo host name (e.g. football.example.com):"
curl --fail --silent --show-error "https://$DEMO_HOST/health" >/dev/null \
  || { warn "https://$DEMO_HOST/health is not reachable"; exit 1; }
curl --fail --silent --show-error "https://$DEMO_HOST/robots.txt" | head -n 3
if uv run --no-project python scripts/set_demo_host.py --check 2>/dev/null; then
  say "The demo host is already set."
else
  uv run --no-project python scripts/set_demo_host.py "$DEMO_HOST"
fi
pause

stage "Version $RELEASE_VERSION"
say "Bumping pyproject.toml, cli/pyproject.toml, web/pyproject.toml, and server.json, then re-testing."
uv run --no-project python - "$RELEASE_VERSION" <<'PY'
import json, re, sys
from pathlib import Path
version = sys.argv[1]
for name in ("pyproject.toml", "cli/pyproject.toml", "web/pyproject.toml"):
    path = Path(name)
    path.write_text(re.sub(r'(?m)^version = ".*"$', f'version = "{version}"', path.read_text(), 1))
path = Path("server.json")
server = json.loads(path.read_text())
server["version"] = version
path.write_text(json.dumps(server, indent=2) + "\n")
PY
uv lock
uv run pytest -q
git --no-pager diff --stat
confirm "Commit 'Release $RELEASE_VERSION'?" || exit 1
git commit -am "Release $RELEASE_VERSION"
git push origin HEAD

stage "Tag and release"
say "The tag starts release.yml: CI, build, PyPI, then the MCP Registry."
confirm "Create and push tag v$RELEASE_VERSION? (a PyPI version can never be reused)" || exit 1
git tag -a "v$RELEASE_VERSION" -m "Release $RELEASE_VERSION"
git push origin "v$RELEASE_VERSION"
open_url "https://github.com/$SLUG/actions/workflows/release.yml"
step "Wait for the Release workflow to finish (approve the pypi job if you added reviewers)."
pause "Press Enter once it is green"

stage "Verify"
say "PyPI package:"
uvx --refresh --from "football-results-cli==$RELEASE_VERSION" football-results competitions \
  | head -c 300; printf '\n'
say "MCP Registry entry:"
curl --fail --silent --show-error \
  "https://registry.modelcontextprotocol.io/v0/servers?search=io.github.$OWNER/football-results" \
  | head -c 400; printf '\n'
step "Tick item 15's registry sub-task and item 19 in docs/ROADMAP.md, then commit."
step "Run the manual chat-client checklist in evals/CHAT_CLIENTS.md against the demo."
pause

finish
}

run_wizard "$@"; exit
